KG42.register("slice-clusters-53c998b75bbd78b6fb1cadf5",{"id":"22-decentralized_flexibility_markets::v142-d-K004","paper":"22-decentralized_flexibility_markets","title":"Linkage from agreed contract prices to payment obligations and interpretation of case revenue","source_pointer":"/clusters/85","node_ids":["COMP-535650ecb2e046e9","COMP-739917e3869e45a6","COMP-10be07664c6496b7","COMP-75186ff50e007d27","KG31-5be8ae1142e7d54c"],"rule_refs":["22-decentralized_flexibility_markets::v141-c-R007","22-decentralized_flexibility_markets::v141-c-R006","22-decentralized_flexibility_markets::v141-c-R003","22-decentralized_flexibility_markets::v141-c-R001"],"visible_rule_refs":["22-decentralized_flexibility_markets::v141-c-R007","22-decentralized_flexibility_markets::v141-c-R006","22-decentralized_flexibility_markets::v141-c-R003","22-decentralized_flexibility_markets::v141-c-R001"],"suppressed_rule_refs":[],"edges":[{"global_edge_id":"S-ee3eaebb85c6bcef","source":"COMP-535650ecb2e046e9","target":"COMP-739917e3869e45a6","type":"links","assertion_ids":["22-decentralized_flexibility_markets::v141-c-R007::E::v141-c-R007-E001"],"rule_refs":["22-decentralized_flexibility_markets::v141-c-R007"],"internal":false},{"global_edge_id":"S-bddcca51aa21463d","source":"COMP-10be07664c6496b7","target":"COMP-535650ecb2e046e9","type":"links","assertion_ids":["22-decentralized_flexibility_markets::v141-c-R006::E::v141-c-R006-E001"],"rule_refs":["22-decentralized_flexibility_markets::v141-c-R006"],"internal":false},{"global_edge_id":"S-1b272357ba647227","source":"COMP-75186ff50e007d27","target":"COMP-10be07664c6496b7","type":"links","assertion_ids":["22-decentralized_flexibility_markets::v141-c-R003::E::v141-c-R003-E001"],"rule_refs":["22-decentralized_flexibility_markets::v141-c-R003"],"internal":false}],"unresolved_rule_refs":[],"interface_annotations":[{"connection_id":"v142-d-L011","from_chain_id":"v141-c-R006","to_chain_id":"v141-c-R007","kind":"functional_coupling","from_refs":["v141-c-R006::phi::v141-c-R006-C001","v141-c-R006::phi::v141-c-R006-C003"],"to_refs":["v141-c-R007::theta::param_contract_price","v141-c-R007::phi::v141-c-R007-C001"],"evidence_ids":["v141-b-g01-E08","v141-b-g01-E10","v141-b-g01-E13","v141-b-g02-e13","v141-b-g02-e24"],"rationale":"The source interprets the price of an agreed contract as the amount the seller receives from the buyer, so there is a functional linkage between the pricing result and the payment obligation. This connection is conditional on an existing agreed contract and does not fabricate proof that bilateral bids are consistent."},{"connection_id":"v142-d-L012","from_chain_id":"v141-c-R003","to_chain_id":"v141-c-R007","kind":"quantity_interface","from_refs":["v141-c-R003::x::v141-c-R003-X003"],"to_refs":["v141-c-R007::theta::param_contract_price"],"evidence_ids":["v141-b-g01-E08","v141-b-g01-E13","v141-b-g02-e21","v141-b-g02-e23"],"rationale":"The contract-tuple price becomes a payment input after the same contract is finally agreed. This interface retains the operational-variable role in bargaining and the fixed-input role in settlement, and does not interpret all temporary bids as payments that have occurred."},{"connection_id":"v142-d-L013","from_chain_id":"v141-c-R001","to_chain_id":"v141-c-R007","kind":"complementary_scope","from_refs":["v141-c-R001::phi::v141-c-R001-C001"],"to_refs":["v141-c-R007::phi::v141-c-R007-C003"],"evidence_ids":["v141-b-g02-e30","v141-b-g02-e31","v141-b-g03-E11"],"rationale":"The resource-lack and non-participation record of the same case is linked with the explanation of zero revenue for these entities in the revenue result; only the result for this specified group is retained, and no general settlement constraint is added."}],"annotation_policy":"Original D connections are annotations, not additional S edges.","empty_after_chain_suppression":false});
